css:
.call{display:flex;align-items:center;gap:22px;background:rgba(0,0,0,.25);padding:18px 36px;border-radius:999px;font-weight:900;font-size:52px}.rec{width:28px;height:28px;border-radius:50%;background:#ff2d2d;animation:pulse .9s ease-in-out infinite!important;animation-play-state:paused!important}.tr{width:1060px;display:flex;flex-direction:column;gap:18px}.ln{font-size:44px;font-weight:600;line-height:1.35;background:#15151f;border-radius:24px;padding:16px 28px;animation:slide .45s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.ln b{color:#8f8fa3;font-weight:600}.ln mark{background:none;color:#111;position:relative;padding:0 6px;background-image:linear-gradient(#ffd23f,#ffd23f);background-repeat:no-repeat;background-size:100% 100%;animation:hl .4s ease-out;animation-delay:calc(var(--t) + var(--d,0s) + .55s);border-radius:6px}@keyframes hl{from{background-size:0% 100%;color:#fff}to{background-size:100% 100%;color:#111}}.live{position:absolute;top:34px;right:44px;font-size:34px;font-weight:900;display:flex;gap:12px;align-items:center}.chips{display:flex;gap:20px;justify-content:center;width:1240px}.cp{background:#fff;color:#111;border-radius:30px;padding:20px 26px;text-align:center}.cp small{display:block;font-size:32px;color:#666;font-weight:600}.cp b{font-size:54px;font-weight:900}.q{background:#fff;color:#111;border-radius:36px;padding:34px 50px;width:960px;box-shadow:0 30px 80px rgba(0,0,0,.35)}.q h3{margin:0;font-size:52px;font-weight:900;display:flex;justify-content:space-between;align-items:center}.q h3 span{font-size:30px;background:#2ee59d;color:#063;padding:6px 18px;border-radius:999px}.qr{display:flex;justify-content:space-between;font-size:40px;font-weight:600;padding:12px 0;border-bottom:2px dashed #e6e6e6;animation:slide .4s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.qr span:last-child{direction:ltr}.qt{font-weight:900;font-size:50px;border:0}.gold{background:radial-gradient(circle at 50% 40%,#ffe9a3,#e8a917 55%,#8a5a00)}.gbig{color:#2a1a00!important;font-size:170px!important;text-align:center;letter-spacing:-3px}.send{background:#111;color:#fff;font-weight:900;font-size:50px;padding:22px 50px;border-radius:26px}.rowc{display:flex;justify-content:space-between;font-size:46px;font-weight:600;padding:14px 0;border-top:2px solid #eadfcd;animation:slide .45s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.rowc b{color:#e8590c;font-weight:900;direction:rtl}
.num{display:inline-flex;width:120px;height:120px;border-radius:32px;background:#ff5a1f;color:#fff;font-weight:900;font-size:90px;align-items:center;justify-content:center}
.say{font-weight:900;font-size:92px;line-height:1.05;text-align:center;max-width:1180px}
.say .y{color:#ffd23f}
.kwb{background:#ffd23f;color:#111;font-weight:900;font-size:120px;padding:18px 56px;border-radius:40px;transform:rotate(-2deg);white-space:nowrap}
.bubble b{color:#ff5a1f}
